BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷111·太祖本纪二·九月定州奏报", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/de96122983ba5859ae5249fe97bf6072d2a7e372/content/books/zizhi-tongjian/vol-290/year-0951/part-08/sources/library/jiuwudaishi-111-september-report/source.txt", "note": "《旧五代史》卷111·太祖本纪二·九月定州奏报，段落 jiu-wudaishi-205deb4a7860-p002663；已核上下文及传主，纸本及异文待核。", "id": "ec760a48-db1d-5067-8719-1ca4ae54c26e"}, {"title": "辽史·卷5·世宗本纪·天禄五年九月遇弑", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/de96122983ba5859ae5249fe97bf6072d2a7e372/content/books/zizhi-tongjian/vol-290/year-0951/part-08/sources/library/liaoshi-005-shizong-death/source.txt", "note": "《辽史》卷5·世宗本纪·天禄五年九月遇弑，段落 liaoshi-7cd182a20e67-p000618；已核上下文及传主，纸本及异文待核。", "id": "86532958-ba87-5d77-baec-70d7d4a4de52"}, {"title": "辽史·卷6·穆宗本纪·应历元年即位", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/de96122983ba5859ae5249fe97bf6072d2a7e372/content/books/zizhi-tongjian/vol-290/year-0951/part-08/sources/library/liaoshi-006-muzong-accession/source.txt", "note": "《辽史》卷6·穆宗本纪·应历元年即位，段落 liaoshi-7cd182a20e67-p000626；已核上下文及传主，纸本及异文待核。", "id": "af731db7-7c50-5ce3-9dc5-fb24a8d4b424"}, {"title": "资治通鉴·卷290·广顺元年·八九月与契丹楚国政变", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/de96122983ba5859ae5249fe97bf6072d2a7e372/content/books/zizhi-tongjian/vol-290/year-0951/part-08/sources/library/tongjian-290-951-september-coups/source.txt", "note": "《资治通鉴》卷290·广顺元年·八九月与契丹楚国政变，段落 zizhi-tongjian-a63549944a71-p003446；已核上下文及传主，纸本及异文待核。", "id": "060f60b1-ebf6-5a2b-a0e3-06b2038f57e7"}, {"title": "新五代史·卷66·楚世家·南唐册封马希萼", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/dd3926f483152113be60d810cbf48dffff7b9b14/content/books/zizhi-tongjian/vol-290/year-0951/part-04/sources/library/xinwudaishi-066-chu-investiture/source.txt", "note": "《新五代史》卷66·楚世家·南唐册封马希萼，段落 xin-wudaishi-b08f244b9241-p003332；已核上下文及传主，纸本及异文待核。", "id": "b5e62597-b257-5d89-895e-8dba38722875"}, {"title": "旧五代史·卷111·太祖本纪二·广顺元年八月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/9e997db426b307c77960efec150970c3a7a81085/content/books/zizhi-tongjian/vol-290/year-0951/part-07/sources/library/jiuwudaishi-111-august-transfers/source.txt", "note": "《旧五代史》卷111·太祖本纪二·广顺元年八月，段落 jiu-wudaishi-205deb4a7860-p002662；已核上下文及传主，纸本及异文待核。", "id": "50c8ce67-1438-536e-a5f9-ce92e7c576f7"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "柴氏（郭威妻）", "aliases": ["圣穆皇后柴氏", "聖穆皇后柴氏"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "郭威的妻子，柴守礼的妹妹、柴荣的姑母。《新五代史》后妃传记她没有儿子，与郭威收养兄长之子柴荣，后称圣穆皇后。本段仅核亲属身份，不将后来皇后称号当作950年在位身份，生卒年尚未录入。", "biography": null, "status": "draft", "id": "9bcfb806-882b-5702-b418-26b2b55a3029"}, {"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "李存瑰", "aliases": ["李瓌", "李瑰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李存瑰，供奉官、赴西川赐诏者。", "biography": null, "status": "draft", "id": "a91449a7-a285-52aa-9c4a-0bf81e533f51"}, {"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}, {"name": "述轧", "aliases": ["述軋"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领。947年耶律德光派他与奚王拽刺、高谟翰驻守洛阳。生卒年、具体家族未载。", "biography": null, "status": "draft", "id": "1ecc60de-19a4-506b-a5c6-e10933ad627e"}, {"name": "沤僧（契丹太宁王）", "aliases": ["沤僧"], "era": "五代十国", "birth_year": null, "death_year": 951, "description": "《资治通鉴》称太宁王、伟王之子。951年九月与述轧作乱，杀害耶律阮，随后被拥立耶律璟的部众杀死。《辽史》本纪此役记察割作乱，具体姓名对应待核，未直接合并。", "biography": null, "status": "draft", "id": "c56126aa-de27-5f8a-87d8-dd139ac7794b"}, {"name": "耶律璟", "aliases": ["耶律述律", "述律王", "寿安王", "壽安王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "耶律德光的长子，小字述律，封寿安王。《资治通鉴》949年条称述律王，记他派骑兵带走石重贵的宠姬赵氏、聂氏；《辽史》穆宗纪可核对姓名和亲支。949年时仍以述律王身份见于记载。", "biography": null, "status": "draft", "id": "81fb2030-5792-5006-be3c-0909be18feec"}, {"name": "王得中", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "上党人，北汉枢密直学士。951年九月受刘崇派遣出使契丹，祝贺新君即位，并请求援兵进攻晋州。生卒年未载。", "biography": null, "status": "draft", "id": "24fc3a64-54f4-5587-8e68-cf8c2b329c89"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "范仁恕", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀吏部尚书、御史中丞。951年九月任中书侍郎兼吏部尚书、同平章事。生卒年未载。", "biography": null, "status": "draft", "id": "f45f5d66-486b-52ca-b506-f2c34b88ccd5"}, {"name": "马希萼", "aliases": ["馬希萼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希范的弟弟、马希广的兄长。947年马希范死时，任武平节度使、知永州事，部分将领主张拥立他，但最终马希广继位。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9d5be246-b5ae-553e-b5c5-a6a875b2c1cd"}, {"name": "许可琼", "aliases": ["許可瓊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "许德勋的儿子，楚国水军指挥使。950年受马希广命率五百艘战舰屯城北津，水军接连南津，由马希崇监军。生卒年未载。", "biography": null, "status": "draft", "id": "31ee592e-a1c4-52e7-8bf7-298a4985dab9"}, {"name": "徐威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国马步都指挥使。951年奉马希萼之命率兵防备朗州军，随后参与政变，囚禁马希萼、拥立马希崇。生卒年尚未录入。", "biography": null, "status": "draft", "id": "a81395a0-0db4-5770-8cc4-b36b3606c3a3"}, {"name": "陈敬迁", "aliases": ["陳敬遷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国左右军马步使。951年与徐威等奉命在长沙城西北立寨防备朗州军，并参与政变。生卒年未载。", "biography": null, "status": "draft", "id": "6b9da951-ff9d-5a1d-8898-a05519fe360b"}, {"name": "鲁公馆", "aliases": ["魯公館"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国水军都指挥使。951年与徐威等奉命设寨防备朗州军，并参与政变。《新五代史》同场记鲁绾，姓名是否对应待核，未直接合并。生卒年未载。", "biography": null, "status": "draft", "id": "712ff646-9597-5357-9ffa-2dd36541995e"}, {"name": "陆孟俊", "aliases": ["陸孟俊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国牙内侍卫指挥使。951年与徐威等设寨防备朗州军，并参与囚禁马希萼、拥立马希崇的政变。生卒年未载。", "biography": null, "status": "draft", "id": "9cdd0a9c-6c68-563a-a248-ebe4bdf18320"}, {"name": "马希崇", "aliases": ["馬希崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希广的庶弟、马希萼的弟弟。947年任楚天策左司马，秘密致信马希萼指责继位安排，又向他报告马希广的言行并约为内应。生卒年尚未录入。", "biography": null, "status": "draft", "id": "7c876e99-eb52-5864-9569-0ede35f9ff7b"}, {"name": "谢彦颙", "aliases": ["謝彥顒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希萼原来的家奴，担任小门使。《资治通鉴》记他受宠后专横，与马希崇产生嫌隙，并获准参加府宴。生卒年未载。", "biography": null, "status": "draft", "id": "38f0eeff-4fb2-57c8-8650-1fe7b690f7fb"}, {"name": "刘言", "aliases": ["劉言"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吉州庐陵人，楚国辰州刺史。951年王逵、周行逢等欲迎他到朗州任副使，他单骑前往，众人废去马光惠后推他为权武平留后。生卒年尚未录入。", "biography": null, "status": "draft", "id": "b32e335e-b386-5ab9-a996-bb31d55c6787"}, {"name": "李观象", "aliases": ["李觀象"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "桂林人，刘言的掌书记。951年劝刘言先要求马希崇杀死马希萼旧将佐，再谋取湖南。生卒年未载。", "biography": null, "status": "draft", "id": "b82d40c1-0625-563a-998e-2f80c6d46927"}, {"name": "杨仲敏", "aliases": ["楊仲敏"], "era": "五代十国", "birth_year": null, "death_year": 951, "description": "楚国都军判官。951年马希崇因畏惧刘言，下令杀死杨仲敏等人，并把首级送往朗州。生卒年此前未载，死亡年为951年。", "biography": null, "status": "draft", "id": "930957b4-1a32-5e00-bad5-8502372f176b"}, {"name": "刘光辅", "aliases": ["劉光輔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希萼的掌书记。951年二月奉命向南唐进贡。生卒年未载。", "biography": null, "status": "draft", "id": "f149dc3c-32e5-5f02-bd24-315df551ceee"}, {"name": "魏师进", "aliases": ["魏師進"], "era": "五代十国", "birth_year": null, "death_year": 951, "description": "楚国牙内指挥使。951年马希崇下令杀死魏师进等人，并把首级送往朗州。此前履历及出生年未载。", "biography": null, "status": "draft", "id": "cb95ac3d-a3af-5341-8052-1f706b8bdc4d"}, {"name": "黄勍", "aliases": ["黃勍"], "era": "五代十国", "birth_year": null, "death_year": 951, "description": "楚国都押牙。951年马希崇下令杀死黄勍等人，并把首级送往朗州。此前履历及出生年未载。", "biography": null, "status": "draft", "id": "52449ddd-2b89-5663-8063-680ac66347d6"}, {"name": "李翊（前辰阳县令）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 951, "description": "楚国前辰阳县令。951年受马希崇之命把被杀将佐的首级送往朗州，遭刘言等指责后惶恐自杀。未与其他时期同名人物合并。", "biography": null, "status": "draft", "id": "ffc500fb-c133-5ce1-aab6-2527550fcd65"}, {"name": "王逵", "aliases": ["王进逵", "王進逵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军指挥使。《新五代史》称王进逵，记为武陵人，早年是静江军士卒。951年与周行逢率修府士兵逃回朗州，参与当地军府事务。生卒年尚未录入。", "biography": null, "status": "draft", "id": "48ca3ee4-cced-5056-8a47-4394d3ad6237"}, {"name": "彭师暠", "aliases": ["彭師暠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "彭士愁的儿子。940年受父亲派遣，率诸酋长向楚交出溪、锦、奖三州官印，请求归降。生卒年未载。", "biography": null, "status": "draft", "id": "9a01204b-6429-53ed-8ca1-76b3143bd4d8"}, {"name": "廖偃", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "廖匡图之子，楚国衡山指挥使。951年与叔父廖匡凝商议扶助被废的马希萼，率庄户和乡人，与彭师暠共同拥立马希萼为衡山王。生卒年未载。", "biography": null, "status": "draft", "id": "d604ed00-6b4d-52ea-bc7d-00a0c995ff48"}, {"name": "廖匡凝", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "廖偃的叔父，楚国节度巡官。951年与廖偃商议扶助马希萼，参与在衡山拥立及组织乡兵。生卒年未载。", "biography": null, "status": "draft", "id": "9e3fbafa-599f-5d16-a9ba-14fd492978c6"}, {"name": "廖匡图", "aliases": ["廖匡圖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚王马希范的幕僚，939年天策府开府时获任学士。与廖匡齐是否有亲属关系本段未载，不因近名建立关系。生卒年未载。", "biography": null, "status": "draft", "id": "8a82ad3a-e5fa-5b3c-b014-7342810d676c"}, {"name": "刘虚己", "aliases": ["劉虛己"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希萼在衡山的判官。951年受派遣向南唐请求援助。生卒年未载。", "biography": null, "status": "draft", "id": "02f394c3-eafc-5396-b7ae-82b2f626e159"}, {"name": "范守牧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希崇的客将。951年奉表向南唐请求援兵。生卒年未载。", "biography": null, "status": "draft", "id": "7e1e642e-7e69-58c3-ac7b-27be139af765"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "边镐", "aliases": ["邊鎬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "金陵人，南唐通事舍人。943年十月任讨张遇贤军监军，用白昌裕为谋主，接连获胜；白昌裕建议开道绕到营后袭击，张遇贤随后逃走被捕。生卒年尚未核。", "biography": null, "status": "draft", "id": "8bcc0004-3382-5f6c-af6e-73ccf4cdd725"}]'::jsonb)
